import { rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

/** Keep the published exclusion list in sync with each catalog build. */
export function writeExclusions(folder: string, exclusions: Record<string, string>): void {
  const file = join(folder, 'README.md')
  const entries = Object.entries(exclusions).sort(([a], [b]) => a.localeCompare(b))
  if (entries.length === 0) {
    rmSync(file, { force: true })
    return
  }
  writeFileSync(
    file,
    [
      '<!-- Generated by the icon builder. -->',
      '',
      '# Excluded icons',
      '',
      'These upstream icons cannot be represented correctly by the current QIcon path converter. They are omitted from the JavaScript exports, TypeScript declarations, and icon list. No replacement artwork is substituted.',
      '',
      '| Icon | Reason |',
      '| --- | --- |',
      ...entries.map(([name, reason]) => `| \`${name}\` | ${reason.replace(/\|/g, '\\|')} |`),
      '',
    ].join('\n'),
  )
}
